var v=new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>().Where(x=>!x.IsTemplate&&x.GenLevel!=null&&x.GenLevel.Name.StartsWith("Basement")).Select(x=>x.Id.IntegerValue+" "+x.Name+" "+x.ViewType+" tmpl "+x.ViewTemplateId.IntegerValue).ToList();
var lv=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l=>l.Elevation).Select(l=>l.Id.IntegerValue+" "+l.Name+" "+Math.Round(l.Elevation*304.8)).ToList();
var keep=new[]{"Doors","Plumbing Fixtures","Specialty Equipment","Parking","Windows"};
var sy=new FilteredElementCollector(doc).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Where(s=>s.Category!=null&&keep.Contains(s.Category.Name)).GroupBy(s=>s.Category.Name+" / "+s.Family.Name).Select(g=>g.Key+" x"+g.Count()).ToList();
var ft=new FilteredElementCollector(doc).OfClass(typeof(FloorType)).Cast<FloorType>().Select(f=>f.Id.IntegerValue+" "+f.Name).ToList();
var fi=new FilteredElementCollector(doc).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().GroupBy(f=>f.Category.Name+" / "+f.Symbol.Name+" / "+(doc.GetElement(f.LevelId)==null?"-":doc.GetElement(f.LevelId).Name)).Select(g=>g.Key+": "+g.Count()).ToList();
return new{doc.Title,v,lv,sy,ft,fi,walls=new FilteredElementCollector(doc).OfClass(typeof(Wall)).GetElementCount(),floors=new FilteredElementCollector(doc).OfClass(typeof(Floor)).GetElementCount(),modified=doc.IsModified,warn=doc.GetWarnings().Count};
